(() => {
  'use strict';

  window.Veilbound = window.Veilbound || {};

  // Hand-authored sheets, kept apart from src/data/characterSprites.js because that file is
  // regenerated by tools/prerender-characters.mjs and says so at the top. Sprites merges the
  // two, with these taking precedence, so a chibi entry survives a regeneration of the other.
  //
  // Built by tools/make-chibi-sheet.mjs from one front-facing figure. Four directions, in the
  // engine's own order (S, E, N, W); see that tool for how the other three are derived and
  // what to pass once authored side and back views exist.
  window.Veilbound.ChibiSprites = Object.freeze({
    kael_chibi: Object.freeze({
      cell: 96,
      directions: 4,
      clips: Object.freeze({
        Idle_A: Object.freeze({ file: 'kael_chibi_Idle_A.png', frames: 2, fps: 4 }),
        Walking_A: Object.freeze({ file: 'kael_chibi_Walking_A.png', frames: 4, fps: 8 }),
        Use_Item: Object.freeze({ file: 'kael_chibi_Use_Item.png', frames: 3, fps: 4 }),
      }),
    }),
  });
})();
